package cn.guihualab.liveai;
import org.junit.Test;import java.io.ByteArrayOutputStream;import static org.junit.Assert.*;
public class PcmTempoTest {
 static byte[] tone(int frames){byte[] pcm=new byte[frames*2];for(int i=0;i<frames;i++){short sample=(short)(18000*Math.sin(2*Math.PI*220*i/48000));pcm[i*2]=(byte)sample;pcm[i*2+1]=(byte)(sample>>8);}return pcm;}
 static byte[] transform(byte[] input,float rate,int step)throws Exception{PcmTempo tempo=new PcmTempo();ByteArrayOutputStream output=new ByteArrayOutputStream();int accounted=0;for(int i=0;i<input.length;i+=step){PcmTempo.Batch b=tempo.push(input,i,Math.min(step,input.length-i),rate);output.write(b.pcm);accounted+=b.mediaFrames;}PcmTempo.Batch last=tempo.finish(rate);output.write(last.pcm);accounted+=last.mediaFrames;assertEquals(input.length/2,accounted);assertEquals(0,tempo.finish(rate).pcm.length);return output.toByteArray();}
 static double pitch(byte[] pcm){int frames=pcm.length/2,start=Math.min(4800,frames/8),end=frames-start,crossings=0;short last=0;for(int i=start;i<end;i++){short sample=(short)((pcm[i*2]&255)|(pcm[i*2+1]<<8));if(last<=0&&sample>0)crossings++;last=sample;}return crossings*48000d/(end-start);}
 @Test public void realPcmDurationChangesWithoutDoublingVoicePitch()throws Exception{byte[] original=tone(96000);for(float rate:new float[]{.5f,1,1.25f,1.5f,2}){byte[] out=transform(original,rate,1920);double actual=(double)out.length/original.length;assertEquals(1/rate,actual,.04);assertEquals(220,pitch(out),8);}assertArrayEquals(original,transform(original,1,1920));}
 @Test public void changingRateDuringOneContinuousStreamPreservesAllMediaAccounting()throws Exception{byte[] input=tone(96000);PcmTempo tempo=new PcmTempo();int count=0,frames=0;for(int i=0;i<input.length;i+=960){float rate=i<input.length/2?1:2;PcmTempo.Batch b=tempo.push(input,i,Math.min(960,input.length-i),rate);count+=b.mediaFrames;frames+=b.pcm.length/2;}PcmTempo.Batch end=tempo.finish(2);count+=end.mediaFrames;frames+=end.pcm.length/2;assertEquals(96000,count);assertEquals(72000,frames,2400);}
 @Test public void tinyIncomingPacketsAndTurnTailAreNotLost()throws Exception{byte[] input=tone(4800);byte[] out=transform(input,2,2);assertEquals(.5,(double)out.length/input.length,.08);try{new PcmTempo().push(input,0,3,2);fail();}catch(IllegalArgumentException expected){}}
}
